using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Animations;
using UnityEngine.Playables;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using Praktikum5.FSM;
using UTS.Characters;

[InitializeOnLoad]
public static class PlayerMotionRepair
{
    const string Root="Assets/CharacterUpgrade";
    const string Raw=Root+"/Animations/Player/RepairRaw/Running.fbx";
    static string Folder=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"Library/ZU_MotionRepair");
    static string last=SessionState.GetString("ZU.MotionRepair.Command","");
    [Serializable] class Command{public string op,nonce;}
    static PlayerMotionRepair(){EditorApplication.update+=Tick;}
    static void Tick(){var f=Path.Combine(Folder,"command.json");if(!File.Exists(f)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;var text=File.ReadAllText(f);if(text==last)return;last=text;SessionState.SetString("ZU.MotionRepair.Command",text);try{var c=JsonUtility.FromJson<Command>(text);if(c.op=="audit")Audit();else if(c.op=="audit-after")Audit(false);else if(c.op=="fix-run-reference")FixRunReference();else if(c.op=="fix-player-references")FixPlayerReferences();else if(c.op=="fit-crouch")FitCrouch();else if(c.op=="apply")Apply();else if(c.op=="rig")Rig();else if(c.op=="refresh")AssetDatabase.Refresh();}catch(Exception e){File.WriteAllText(Path.Combine(Folder,"error.txt"),e.ToString());Debug.LogException(e);}}
    static AnimationClip Clip(string path)=>AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview"));
    static Dictionary<string,Transform> Bones(GameObject go)=>go.GetComponentsInChildren<Transform>().GroupBy(t=>t.name.Split(':').Last()).ToDictionary(g=>g.Key,g=>g.First());
    static float Angle(Vector3 a,Vector3 b,Vector3 c)=>Vector3.Angle(a-b,c-b);
    static float Bend(Vector3 a,Vector3 b,Vector3 c)=>Vector3.Dot(Vector3.ProjectOnPlane(b-(a+c)*.5f,c-a).normalized,Vector3.forward);
    [Serializable] class Frame{public float phase,sourceLeft,sourceRight,fkLeft,fkRight,ikLeft,ikRight,sourcePlaneLeft,fkPlaneLeft,ikPlaneLeft;}
    [Serializable] class AuditResult{public string scene,backup;public Frame[] frames;public float fkError,ikError;public bool playing;}
    static void Audit(bool makeBackup=true){
        if(Application.isPlaying)throw new Exception("Audit in Edit mode");var active=SceneManager.GetActiveScene();if(active.path!="Assets/Scenes/UTS.unity")throw new Exception("Expected current UTS");var player=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var live=player.GetComponent<HumanoidAnimationDriver>().Animator;
        string backup=makeBackup?Root+"/Backups/MotionRepair_"+DateTime.Now.ToString("yyyyMMdd_HHmmss"):File.ReadAllText(Path.Combine(Folder,"backup.txt"));if(makeBackup){Directory.CreateDirectory(backup);AssetDatabase.Refresh();EditorSceneManager.SaveScene(active,backup+"/UTS_BeforeRepair.unity",true);AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(live.runtimeAnimatorController),backup+"/Player_BeforeRepair.controller");File.WriteAllText(Path.Combine(Folder,"backup.txt"),backup);}
        var mi=(ModelImporter)AssetImporter.GetAtPath(Raw);mi.animationType=ModelImporterAnimationType.Generic;mi.avatarSetup=ModelImporterAvatarSetup.NoAvatar;mi.importCameras=false;mi.importLights=false;mi.optimizeGameObjects=false;mi.animationCompression=ModelImporterAnimationCompression.Off;mi.SaveAndReimport();var rawClip=Clip(Raw);var clip=Clip(Root+"/Animations/Player/Running.fbx");
        var scene=EditorSceneManager.NewPreviewScene();var source=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Raw));SceneManager.MoveGameObjectToScene(source,scene);var sourceBones=Bones(source);var outputs=new List<GameObject>();var graphs=new List<PlayableGraph>();var motions=new List<AnimationClipPlayable>();var animators=new List<Animator>();
        try{for(int mode=0;mode<2;mode++){var model=UnityEngine.Object.Instantiate(live.gameObject);SceneManager.MoveGameObjectToScene(model,scene);model.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);foreach(var c in model.GetComponentsInChildren<MonoBehaviour>())c.enabled=false;var a=model.GetComponent<Animator>();a.runtimeAnimatorController=null;a.applyRootMotion=false;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;a.Rebind();var graph=PlayableGraph.Create("Run source comparison");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var motion=AnimationClipPlayable.Create(graph,clip);motion.SetApplyFootIK(mode==1);var output=AnimationPlayableOutput.Create(graph,"Pose",a);output.SetSourcePlayable(motion);graph.Play();outputs.Add(model);graphs.Add(graph);motions.Add(motion);animators.Add(a);}
            var frames=new List<Frame>();for(int i=0;i<32;i++){float phase=i/32f;rawClip.SampleAnimation(source,rawClip.length*phase);var sl=sourceBones["LeftUpLeg"].position;var sk=sourceBones["LeftLeg"].position;var sf=sourceBones["LeftFoot"].position;var sr=sourceBones["RightUpLeg"].position;var rk=sourceBones["RightLeg"].position;var rf=sourceBones["RightFoot"].position;var frame=new Frame{phase=phase,sourceLeft=Angle(sl,sk,sf),sourceRight=Angle(sr,rk,rf),sourcePlaneLeft=Bend(sl,sk,sf)};for(int mode=0;mode<2;mode++){motions[mode].SetTime(clip.length*phase);graphs[mode].Evaluate(0);var a=animators[mode];var ul=a.GetBoneTransform(HumanBodyBones.LeftUpperLeg).position;var ll=a.GetBoneTransform(HumanBodyBones.LeftLowerLeg).position;var lf=a.GetBoneTransform(HumanBodyBones.LeftFoot).position;var ur=a.GetBoneTransform(HumanBodyBones.RightUpperLeg).position;var lr=a.GetBoneTransform(HumanBodyBones.RightLowerLeg).position;var rr=a.GetBoneTransform(HumanBodyBones.RightFoot).position;if(mode==0){frame.fkLeft=Angle(ul,ll,lf);frame.fkRight=Angle(ur,lr,rr);frame.fkPlaneLeft=Bend(ul,ll,lf);}else{frame.ikLeft=Angle(ul,ll,lf);frame.ikRight=Angle(ur,lr,rr);frame.ikPlaneLeft=Bend(ul,ll,lf);}}frames.Add(frame);}
            var result=new AuditResult{scene=active.path,backup=backup,playing=Application.isPlaying,frames=frames.ToArray(),fkError=frames.Average(f=>(Mathf.Abs(f.sourceLeft-f.fkLeft)+Mathf.Abs(f.sourceRight-f.fkRight))*.5f),ikError=frames.Average(f=>(Mathf.Abs(f.sourceLeft-f.ikLeft)+Mathf.Abs(f.sourceRight-f.ikRight))*.5f)};File.WriteAllText(Path.Combine(Folder,makeBackup?"run-audit.json":"run-audit-after.json"),JsonUtility.ToJson(result,true));
        }finally{foreach(var graph in graphs)if(graph.IsValid())graph.Destroy();EditorSceneManager.ClosePreviewScene(scene);}
    }
    static void Rig(){var lines=new List<string>();foreach(var path in new[]{Raw,Root+"/Animations/Player/Running.fbx",Root+"/Animations/Player/Crouching Idle.fbx",Root+"/Models/Humanoid.fbx",Root+"/Models/PlayerChar.fbx"}){var mi=(ModelImporter)AssetImporter.GetAtPath(path);lines.Add(path+" avatarSetup="+mi.avatarSetup+" source="+AssetDatabase.GetAssetPath(mi.sourceAvatar));var go=AssetDatabase.LoadAssetAtPath<GameObject>(path);var bones=Bones(go);foreach(var name in new[]{"Hips","LeftUpLeg","LeftLeg","LeftFoot","LeftArm","LeftForeArm","Spine"}){var t=bones[name];lines.Add(name+" actualName="+t.name+" pos="+t.localPosition+" rot="+t.localRotation+" world="+t.rotation);var sk=mi.humanDescription.skeleton.FirstOrDefault(b=>b.name==t.name);lines.Add("  Avatar ref="+sk.rotation+" position="+sk.position);}lines.Add("NAMES="+string.Join(",",bones.Values.Select(t=>t.name)));}File.WriteAllLines(Path.Combine(Folder,"rig.txt"),lines);}
    static void FixRunReference(){if(Application.isPlaying)throw new Exception("Edit mode required");var path=Root+"/Animations/Player/Running.fbx";var mi=(ModelImporter)AssetImporter.GetAtPath(path);var avatar=AssetDatabase.LoadAllAssetsAtPath(Root+"/Models/PlayerChar.fbx").OfType<Avatar>().First(a=>a.isValid&&a.isHuman);var backup=File.ReadAllText(Path.Combine(Folder,"backup.txt"));Directory.CreateDirectory(backup+"/ImportSettings");var file=backup+"/ImportSettings/Running.fbx.meta.txt";if(!File.Exists(file))File.Copy(path+".meta",file);mi.avatarSetup=ModelImporterAvatarSetup.CopyFromOther;mi.sourceAvatar=avatar;mi.SaveAndReimport();File.WriteAllText(Path.Combine(Folder,"run-reference-fixed.txt"),"Running uses PlayerChar reference Avatar; source FBX motion preserved");}
    static void FixPlayerReferences(){
        if(Application.isPlaying)throw new Exception("Edit mode required");var active=SceneManager.GetActiveScene();if(active.path!="Assets/Scenes/UTS.unity")throw new Exception("Expected current UTS");var avatarPath=Root+"/Models/PlayerChar.fbx";var model=AssetDatabase.LoadAssetAtPath<GameObject>(avatarPath);var avatar=AssetDatabase.LoadAllAssetsAtPath(avatarPath).OfType<Avatar>().First(a=>a.isValid&&a.isHuman);var names=new HashSet<string>(model.GetComponentsInChildren<Transform>().Select(t=>t.name));var backup=File.ReadAllText(Path.Combine(Folder,"backup.txt"));Directory.CreateDirectory(backup+"/ImportSettings");var changed=new List<string>();
        foreach(var name in new[]{"Idle","Running","Crouching Idle","Crouched Walking","Punching"}){var path=Root+"/Animations/Player/"+name+".fbx";var go=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(go.GetComponentsInChildren<Transform>().Skip(1).Any(t=>!names.Contains(t.name)))throw new Exception("Clip skeleton does not match PlayerChar: "+name);var file=backup+"/ImportSettings/"+name+".fbx.meta.txt";if(!File.Exists(file))File.Copy(path+".meta",file);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.avatarSetup=ModelImporterAvatarSetup.CopyFromOther;mi.sourceAvatar=avatar;mi.SaveAndReimport();changed.Add(path);}
        var player=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var animator=player.GetComponent<HumanoidAnimationDriver>().Animator;var controller=animator.runtimeAnimatorController as AnimatorController;var state=controller.layers[0].stateMachine.states.Single(s=>s.state.name=="Crouching").state;var tree=state.motion as BlendTree;if(!tree)throw new Exception("Expected existing crouch blend tree");var children=tree.children;if(children.Length!=2||AssetDatabase.GetAssetPath(children[0].motion)!=Root+"/Animations/Player/Crouch Idle Balanced.anim"||AssetDatabase.GetAssetPath(children[1].motion)!=Root+"/Animations/Player/Crouch Walk Balanced.anim")throw new Exception("User crouch motions changed; inspect before replacing");children[0].motion=Clip(Root+"/Animations/Player/Crouching Idle.fbx");children[1].motion=Clip(Root+"/Animations/Player/Crouched Walking.fbx");tree.children=children;EditorUtility.SetDirty(tree);EditorUtility.SetDirty(controller);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(active);File.WriteAllLines(Path.Combine(Folder,"player-references-fixed.txt"),changed.Concat(new[]{"Crouch motions restored to original FBX clips; previous generated pose assets retained as backup, no longer played."}));
    }
    static void FitCrouch(){if(Application.isPlaying)throw new Exception("Edit mode required");var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/UTS.unity")throw new Exception("Expected current UTS");var player=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var so=new SerializedObject(player);var property=so.FindProperty("crouchHeight");if(Mathf.Abs(property.floatValue-1.6f)>.001f)throw new Exception("Crouch collider changed since inspection; inspect before editing");property.floatValue=1.5f;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(player);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText(Path.Combine(Folder,"collider-fit.txt"),"Crouch height 1.60 -> 1.50 m: original walk max sampled head height 1.317 m + head allowance fits. Standing collider unchanged.");}
    static void Apply(){throw new Exception("Compare source before editing");}
}
